-- Reconcile live admin revenue reporting with the intended ledger rules.
-- Include current admin_recovery entries in all_time_profit, while excluding historical migrated recovery entries.
-- Preserve existing ledger history; this migration only replaces reporting functions.

CREATE OR REPLACE FUNCTION public.admin_profit_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$ DECLARE v_admin uuid; v_unallocated_recovery numeric; v_available_balance numeric; BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'not authorized' USING errcode='42501'; END IF; SELECT auth.uid() INTO v_admin; SELECT COALESCE(SUM(CASE WHEN entry_type='credit' THEN amount_pkr WHEN entry_type IN ('debit','reversal') THEN -amount_pkr ELSE 0 END),0) INTO v_unallocated_recovery FROM public.recovery_fund_ledger WHERE user_id IS NULL; SELECT COALESCE(SUM(amount),0) INTO v_available_balance FROM public.ledger_entries WHERE user_id=v_admin AND entry_type IN ('platform_admin_profit','platform_profit','unassigned_referral','referral_commission','referral_commission_adjustment','referral_commission_reversal','referral_commission_reserve_adjustment','admin_recovery','admin_adjustment','withdrawal','withdrawal_refund') AND NOT (entry_type='admin_recovery' AND COALESCE(note,'') ILIKE 'Historical recovery allocation migrated from Admin Recovery Reserve%') AND NOT (entry_type='unassigned_referral' AND COALESCE(note,'') ILIKE '%Ahmad31 purchase%'); RETURN jsonb_build_object('total_admin_profit',COALESCE((SELECT SUM(CASE WHEN transaction_type='platform_profit' THEN profit_amount ELSE -profit_amount END) FROM public.admin_profit_ledger),0),'total_profit',COALESCE((SELECT SUM(CASE WHEN transaction_type='platform_profit' THEN profit_amount ELSE -profit_amount END) FROM public.admin_profit_ledger),0),'platform_profit',COALESCE((SELECT SUM(CASE WHEN transaction_type='platform_profit' THEN profit_amount ELSE -profit_amount END) FROM public.admin_profit_ledger),0),'referral_profit',COALESCE((SELECT SUM(amount) FROM public.ledger_entries WHERE user_id=v_admin AND entry_type IN ('referral_commission','referral_commission_adjustment','referral_commission_reversal','referral_commission_reserve_adjustment','unassigned_referral') AND NOT (entry_type='unassigned_referral' AND COALESCE(note,'') ILIKE '%Ahmad31 purchase%')),0),'undistributed_indirect_referral_pool',COALESCE((SELECT SUM(amount) FROM public.ledger_entries WHERE user_id=v_admin AND entry_type='platform_profit' AND COALESCE(note,'') ILIKE 'Undistributed indirect referral pool settled to admin%'),0),'admin_recovery_total',COALESCE((SELECT SUM(amount) FROM public.ledger_entries WHERE user_id=v_admin AND entry_type='admin_recovery' AND COALESCE(note,'') NOT ILIKE 'Historical recovery allocation migrated from Admin Recovery Reserve%'),0),'all_time_profit',COALESCE((SELECT SUM(amount) FROM public.ledger_entries WHERE user_id=v_admin AND entry_type IN ('platform_admin_profit','platform_profit','referral_commission','referral_commission_adjustment','referral_commission_reversal','referral_commission_reserve_adjustment','unassigned_referral','admin_recovery') AND NOT (entry_type='admin_recovery' AND COALESCE(note,'') ILIKE 'Historical recovery allocation migrated from Admin Recovery Reserve%') AND NOT (entry_type='unassigned_referral' AND COALESCE(note,'') ILIKE '%Ahmad31 purchase%')),0)+COALESCE((SELECT SUM(amount) FROM public.ledger_entries WHERE user_id=v_admin AND entry_type='admin_adjustment' AND COALESCE(note,'') ILIKE 'Reward budget overrun expense:%'),0),'today_profit',COALESCE((SELECT SUM(CASE WHEN transaction_type='platform_profit' THEN profit_amount ELSE -profit_amount END) FROM public.admin_profit_ledger WHERE (created_at AT TIME ZONE 'Asia/Karachi')::date=(now() AT TIME ZONE 'Asia/Karachi')::date),0),'today_admin_earnings',COALESCE((SELECT SUM(amount) FROM public.ledger_entries WHERE user_id=v_admin AND entry_type IN ('platform_admin_profit','unassigned_referral','referral_commission','referral_commission_adjustment','referral_commission_reversal','referral_commission_reserve_adjustment') AND (created_at AT TIME ZONE 'Asia/Karachi')::date=(now() AT TIME ZONE 'Asia/Karachi')::date AND COALESCE(note,'') NOT ILIKE '%Ahmad31 purchase%'),0),'month_profit',COALESCE((SELECT SUM(CASE WHEN transaction_type='platform_profit' THEN profit_amount ELSE -profit_amount END) FROM public.admin_profit_ledger WHERE date_trunc('month',created_at AT TIME ZONE 'Asia/Karachi')=date_trunc('month',now() AT TIME ZONE 'Asia/Karachi')),0),'unassigned_referral',COALESCE((SELECT SUM(amount) FROM public.ledger_entries WHERE user_id=v_admin AND entry_type='unassigned_referral' AND COALESCE(note,'') NOT ILIKE '%Ahmad31 purchase%'),0),'total_unassigned_referral',COALESCE((SELECT SUM(amount) FROM public.ledger_entries WHERE user_id=v_admin AND entry_type='unassigned_referral' AND COALESCE(note,'') NOT ILIKE '%Ahmad31 purchase%'),0),'unallocated_recovery',v_unallocated_recovery,'unallocated_recovery_withdrawable',false,'admin_platform_total',COALESCE((SELECT SUM(amount) FROM public.ledger_entries WHERE user_id=v_admin AND entry_type IN ('platform_admin_profit','platform_profit','unassigned_referral','admin_recovery','admin_adjustment') AND NOT (entry_type='admin_recovery' AND COALESCE(note,'') ILIKE 'Historical recovery allocation migrated from Admin Recovery Reserve%') AND NOT (entry_type='unassigned_referral' AND COALESCE(note,'') ILIKE '%Ahmad31 purchase%')),0),'retained_reward_budget',0,'available_balance',v_available_balance,'available_platform_funds',v_available_balance,'admin_own_balance',v_available_balance,'total_withdrawn',COALESCE((SELECT SUM(amount) FROM public.withdrawals WHERE user_id=v_admin AND status='paid'),0),'withdrawn_balance',COALESCE((SELECT SUM(amount) FROM public.withdrawals WHERE user_id=v_admin AND status='paid'),0),'pending_withdrawals',COALESCE((SELECT SUM(amount) FROM public.withdrawals WHERE user_id=v_admin AND status IN ('pending','approved','processing','under_review')),0),'pending_balance',COALESCE((SELECT SUM(amount) FROM public.withdrawals WHERE user_id=v_admin AND status IN ('pending','approved','processing','under_review')),0),'total_owed_to_users',COALESCE((SELECT SUM(b) FROM (SELECT user_id,SUM(amount) b FROM public.ledger_entries WHERE entry_type IN ('ad_reward','referral_commission','referral_commission_lock','admin_adjustment','withdrawal','withdrawal_refund') GROUP BY user_id) x WHERE b>0),0),'users_with_balance',COALESCE((SELECT COUNT(*) FROM (SELECT user_id,SUM(amount) b FROM public.ledger_entries WHERE entry_type IN ('ad_reward','referral_commission','referral_commission_lock','admin_adjustment','withdrawal','withdrawal_refund') GROUP BY user_id) x WHERE b>0),0),'users_in_debt',COALESCE((SELECT -SUM(b) FROM (SELECT user_id,SUM(amount) b FROM public.ledger_entries WHERE entry_type IN ('ad_reward','referral_commission','referral_commission_lock','admin_adjustment','withdrawal','withdrawal_refund') GROUP BY user_id) x WHERE b<0),0),'platform_withdrawn_paid',COALESCE((SELECT SUM(amount) FROM public.withdrawals WHERE status='paid'),0),'platform_withdrawals_pending',COALESCE((SELECT SUM(amount) FROM public.withdrawals WHERE status IN ('pending','approved','processing','under_review')),0)); END; $function$;


CREATE OR REPLACE FUNCTION public.admin_profit_ledger_page()
 RETURNS SETOF jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$ SELECT jsonb_build_object('id',x.id,'date',x.created_at,'created_at',x.created_at,'purchase_id',x.purchase_id,'user_id',x.user_id,'user_name',x.user_name,'plan_name',x.plan_name,'purchase_amount',x.purchase_amount,'profit_percentage',x.profit_percentage,'amount',x.amount,'admin_profit',x.amount,'status',x.status,'source',x.source,'category',x.category) FROM (SELECT l.id,l.created_at,l.purchase_id,l.user_id,p.full_name AS user_name,pl.name AS plan_name,l.gross_amount AS purchase_amount,l.profit_percentage,CASE WHEN l.transaction_type='platform_profit_reversal' THEN -l.profit_amount ELSE l.profit_amount END AS amount,l.status,l.transaction_type AS source,'platform_profit'::text AS category FROM public.admin_profit_ledger l JOIN public.profiles p ON p.id=l.user_id JOIN public.plans pl ON pl.id=l.plan_id WHERE public.is_admin() UNION ALL SELECT le.id,le.created_at,NULL::uuid AS purchase_id,le.user_id,p.full_name AS user_name,NULL::text AS plan_name,NULL::numeric AS purchase_amount,NULL::numeric AS profit_percentage,le.amount,'completed'::text AS status,COALESCE(le.note,le.entry_type) AS source,le.entry_type AS category FROM public.ledger_entries le LEFT JOIN public.profiles p ON p.id=le.user_id WHERE public.is_admin() AND le.user_id=auth.uid() AND le.entry_type IN ('unassigned_referral','referral_commission_adjustment','referral_commission_reversal','referral_commission_reserve_adjustment','admin_recovery','admin_adjustment','withdrawal','withdrawal_refund')) x ORDER BY x.created_at DESC; $function$;
